import {PETS,MIRROR,captureChance} from './campaign-pet-data.mjs';
const TAU=Math.PI*2;
const spriteClips=new WeakMap();
function sprite(c,img,f,height){
 if(!img||!f)return;const r=f.rect,scale=height/f.naturalHeight,a=f.anchor;c.save();c.scale(scale,scale);c.translate(-a[0],-a[1]);
 if(f.clipRuns&&typeof Path2D!=='undefined'){let path=spriteClips.get(f);if(!path){path=new Path2D();for(const [y,x,width]of f.clipRuns)path.rect(x,y,width,1);spriteClips.set(f,path);}c.clip(path);}
 c.drawImage(img,...r,0,0,r[2],r[3]);c.restore();
}
function petSkillEffects(c,w,f,art,d){for(const fx of f.skillFx||[]){const age=w.time-fx.born,t=age/fx.duration;if(t<0||t>=1)continue;const frame=art.petGrowthMeta?.fx.frames[d.row*3+fx.index];if(!frame||!art.petFxImage)continue;const r=frame.rect,size=fx.size*(.8+.2*Math.min(1,t*5)),h=size*r[3]/r[2];c.save();c.globalAlpha=Math.min(1,t*9)*(1-Math.max(0,(t-.65)/.35));c.drawImage(art.petFxImage,...r,fx.x-size/2,fx.y-h*.8,size,h);c.restore();}}
export function drawCompanion(c,w,art,alpha=1){
 const f=w.companion;if(!f||f.hp<=0)return;const d=PETS[f.petKind],form=f.form||0,walking=f.state==='walk'&&art.petGrowthMeta?.walks[form],meta=walking?art.petGrowthMeta.walks[form]:form?art.petGrowthMeta?.forms[form]:art.petMeta,img=walking?art['petWalk'+form]:form?art['petForm'+form]:art.petImage;
 const frame=walking?Math.floor((f.walkPhase||0)*8)%8:f.hit>0?5:f.attackAt||f.attackPoseUntil>w.time?4:Math.floor(w.fxTime*3)%2,source=meta?.frames?.[d.row*(walking?8:6)+frame];if(!source||!img)return;
 const height=d.height[form]+12,x=f.prevX+(f.x-f.prevX)*alpha,y=f.prevY+(f.y-f.prevY)*alpha;petSkillEffects(c,w,f,art,d);c.save();c.fillStyle='#07130d66';c.beginPath();c.ellipse(x,y-1,23,5,0,0,TAU);c.fill();c.translate(x,y);c.scale(f.face,1);const since=w.time-(f.recalledAt??f.born);c.globalAlpha=Math.max(.1,Math.min(1,since*3));sprite(c,img,source,height);c.restore();
 c.save();c.font='11px "Microsoft YaHei"';c.textAlign='center';c.fillStyle='#c7e4b7';c.fillText('同伴 · '+d.name,x,y-height-25);c.fillStyle='#06121ecc';c.fillRect(x-30,y-height-18,60,10);c.fillStyle='#a8cf98';c.fillRect(x-29,y-height-17,58*f.hp/f.maxHp,3);c.fillStyle='#70b8cd';c.fillRect(x-29,y-height-12,58*f.mp/f.maxMp,2);c.restore();
 for(const s of f.shots){const angle=Math.atan2(s.y-s.py,s.x-s.px);c.save();c.translate(s.x,s.y);c.rotate(angle);c.shadowColor=d.color;c.shadowBlur=8;c.fillStyle=d.color;c.strokeStyle=d.color;c.lineWidth=2;c.beginPath();c.moveTo(-20,0);c.lineTo(7,0);c.stroke();c.beginPath();if(f.petKind==='mossdeer'){c.ellipse(0,0,9,4,-.3,0,TAU);}else{c.moveTo(11,0);c.lineTo(-5,-5);c.lineTo(-9,0);c.lineTo(-5,5);c.closePath();}c.fill();c.fillStyle='#fff1d1';c.fillRect(-2,-1,7,2);c.restore();}
 const hit=f.strike;if(hit&&w.time-hit.at<.32){const t=(w.time-hit.at)/.32;c.save();c.globalAlpha=1-t;c.strokeStyle=d.color;c.lineWidth=2;c.shadowColor=d.color;c.shadowBlur=7;if(f.petKind==='emberwing'){for(let i=-1;i<=1;i++){c.beginPath();c.arc(hit.x+i*10,hit.y,19+t*23,-1.3,1.2);c.stroke();}}else{c.beginPath();c.arc(hit.x,hit.y,6+t*25,0,TAU);c.stroke();}c.restore();}
}
export function drawPets(c,w,art,alpha=1){drawCompanion(c,w,art,alpha);const cc=w.campaign,e=w.targets.find(t=>t.id===cc.wildPetId);if(!e)return;const d=PETS[e.petKind],img=art.petImage,meta=art.petMeta;
 if(e.hp>0){const walking=e.state==='walk'&&!e.hit&&!e.attackAt&&art.petGrowthMeta?.walks[0],m=walking?art.petGrowthMeta.walks[0]:meta,sourceImage=walking?art.petWalk0:img,frame=e.hit>0?5:e.attackAt?4:walking?Math.floor(e.cycle*40/130*8)%8:Math.floor(w.fxTime*3)%2,index=d.row*(walking?8:6)+frame,f=m?.frames?.[index];c.save();c.translate(e.prevX+(e.x-e.prevX)*alpha,e.prevY+(e.y-e.prevY)*alpha);c.scale(e.face,1);c.globalAlpha=Math.min(1,(w.time-e.born)*2);sprite(c,sourceImage,f,58);c.restore();
  c.save();c.fillStyle='#050d18d9';c.fillRect(e.x-59,e.y-e.h-38,118,7);c.fillStyle=d.color;c.fillRect(e.x-58,e.y-e.h-37,116*e.hp/e.maxHp,5);c.font='12px "Microsoft YaHei"';c.textAlign='center';c.fillStyle=d.color;c.fillText(d.name,e.x,e.y-e.h-48);c.font='10px "Microsoft YaHei"';c.fillStyle='#eee0b8';c.fillText(`${Math.ceil(e.hp)} / ${e.maxHp} · 捕捉 ${Math.round(captureChance(e.hp,e.maxHp,cc.progression)*100)}%`,e.x,e.y-e.h-17);
  if(e.attackAt){const t=Math.min(1,(e.attackAt-w.time)/.6);c.globalAlpha=.7*(1-t)+.2;c.strokeStyle=d.color;c.lineWidth=2;c.beginPath();c.ellipse(e.x+e.face*48,e.y-3,100,13,0,0,TAU);c.stroke();}c.restore();
 }
 const a=cc.capture?.attempt,r=cc.capture?.result;if(a){const p=w.player,t=Math.min(1,(w.time-a.started)/MIRROR.channel);if(art.mirrorImage&&meta?.mirror){const r=meta.mirror.frames[1].rect,size=150*(1-t*.35);c.save();c.globalAlpha=.5+.3*t;c.drawImage(art.mirrorImage,...r,e.x-size/2,e.y-size*.9,size,size*r[3]/r[2]);c.restore();}c.save();c.strokeStyle=d.color;c.shadowColor=d.color;c.shadowBlur=14;c.lineWidth=2;c.beginPath();c.moveTo(p.x,p.y-55);c.quadraticCurveTo((p.x+e.x)/2,p.y-140,e.x,e.y-30);c.stroke();for(let i=0;i<3;i++){c.beginPath();c.ellipse(e.x,e.y-30,55*(1-t*.5)+i*8,24+i*7,w.fxTime*.8+i,0,TAU);c.stroke();}c.restore();}
 if(r&&w.time-r.at<1.2){const age=w.time-r.at;c.save();c.globalAlpha=Math.max(0,1-age/1.2);c.strokeStyle=r.success?'#f6d596':d.color;c.lineWidth=3;c.beginPath();c.arc(e.x,e.y-35,35+age*70,0,TAU);c.stroke();c.fillStyle='#f5e4bd';c.font='bold 19px serif';c.textAlign='center';c.fillText(r.success?'收伏成功':'挣脱镜光',e.x,e.y-100-age*25);c.restore();}
 const strike=cc.petStrike;if(strike&&w.time-strike.at<.3){const t=(w.time-strike.at)/.3;c.save();c.globalAlpha=1-t;c.strokeStyle=PETS[strike.kind].color;c.shadowColor=c.strokeStyle;c.shadowBlur=14;c.lineWidth=4;c.beginPath();c.arc(strike.x,strike.y,40+t*60,-1.5,1.5);c.stroke();c.restore();}
}
